public void setValueToDayColumn(TransDate _date, str _value)
{
    str                                     fieldname;
    int                                     fieldId;

    fieldname = strFmt('%1%2','HoursDay',dayOfMth(_date));
    fieldId = fieldName2Id(tableNum(NVTimeSheetLines),fieldname);
    this.(fieldId) = _value;
}

public str getValueFromDate(TransDate _date)
{
    str                                     fieldname;
    int                                     fieldId;

    fieldname = strFmt('%1%2','HoursDay',dayOfMth(_date));
    fieldId = fieldName2Id(tableNum(NVTimeSheetLines), fieldname);
    return this.(fieldId);
}

public void setValueToLeaveColumn(int _id, int _value = 1)
{
    str                                     fieldname;
    int                                     fieldId;

    fieldname = strFmt('%1%2','LeaveType',_id);
    fieldId = fieldName2Id(tableNum(NVTimeSheetLines), fieldname);
    this.(fieldId) = this.(fieldId) + _value;
}

public static FieldId dateToFieldId(TransDate _date)
{
    str                                     fieldname;
    int                                     fieldId;

    fieldname = strFmt('%1%2','HoursDay',dayOfMth(_date));
    fieldId = fieldName2Id(tableNum(NVTimeSheetLines), fieldname);

    return fieldId;
}

public static NVTimeSheetLines find(RefRecId _headerId, HcmPersonnelNumberId _empId, boolean _forUpdate = true)
{
    NVTimeSheetLines    lines;

    select firstonly lines
        where lines.TimeSheetHeader == _headerId
        && lines.EmpId == _empId;

    if(_forUpdate)
        lines.selectForUpdate(true);

    return lines;
}

public static NVTimeSheetLines findRecId(RefRecId _recId, boolean _forUpdate = true)
{
    NVTimeSheetLines    lines;

    select firstonly crosscompany lines
        where lines.RecId == _recId;

    if(_forUpdate)
        lines.selectForUpdate(true);

    return lines;
}

public void update()
{
    this.ActualWorkingHours = this.getTotalActualHours();
    this.CalcNightHours     = this.getTotalNightHours();

    NVHcmESSChangeLog::insertRef(this.TableId, this.RecId);

    super();
}

public void updateSync()
{
    this.update();

    NVHcmESSChangeLog changeLog = NVHcmESSChangeLog::insertRef(this.TableId, this.RecId);
    if(changeLog)
    {
        NVHcmProcessESSChangeLog processChangeLog = NVHcmProcessESSChangeLog::construct();

        processChangeLog.parmChangeLogRecId(changeLog.RecId);
        processChangeLog.run();
    }
}

public int getWorkedDays()
{
    int     totalWorkedDays = 0;
    int     lastDayOFMonth = dayOfMth(this.timeSheetHeader().EndDate);

    for(int day = 1; day<=lastDayOFMonth; day++)
    {
        FieldName   fieldName = "HoursDay" + int2str(day);
        int         fieldid = fieldName2Id(tableNum(NVTimeSheetLines), fieldName);

        int totalHours = this.convertStringToInt(this.(fieldid));

        if(totalHours > 0)
            totalWorkedDays++;
    }

    return totalWorkedDays;
}

public int getWorkedDaysDate(date _startDate, date _endDate)
{
    NvTimeSheetHeader timesheet = this.timeSheetHeader();
    int     totalWorkedDays = 0;
    int     firstDay            = dayOfMth(_startDate);
    int     lastDay             = dayOfMth(_endDate);

    for(int day = firstDay; day <= lastDay; day++)
    {
        FieldName   fieldName = "HoursDay" + int2str(day);
        int         fieldid = fieldName2Id(tableNum(NVTimeSheetLines), fieldName);

        int totalHours = this.convertStringToInt(this.(fieldid));

        if(totalHours > 0)
            totalWorkedDays++;
    }

    return totalWorkedDays;
}

private int getTotalActualHours()
{
    int     lastDayOFMonth = dayOfMth(this.timeSheetHeader().EndDate);
    int     totalHours = 0;

    for(int day = 1; day<=lastDayOFMonth; day++)
    {
        FieldName   fieldName = "HoursDay" + int2str(day);
        int         fieldid = fieldName2Id(tableNum(NVTimeSheetLines),fieldName);

        totalHours += this.convertStringToInt(this.(fieldid));

    }
    return totalHours;
}

private int convertStringToInt(str _hours)
{
    int num = 0;
    try
    {
        num = str2Num(_hours);
    }
    catch
    {
        num = 0;
    }
    return num;
}

public NvTimeSheetHeader timeSheetHeader()
{
    NvTimeSheetHeader   header;

    select firstonly crosscompany header
        where header.RecId == this.TimeSheetHeader;

    return header;
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();
    int lastDayOFMonth = dayOfMth(this.timeSheetHeader().EndDate);
    for(int day = 1; day<=lastDayOFMonth; day++)
    {
        FieldName   fieldName = "HoursDay" + int2str(day);
        int         fieldid = fieldName2Id(tableNum(NVTimeSheetLines),fieldName);

        if(this.orig().(fieldId) != this.(fieldId)
            && (NVTimeSheetLinesNoOverwriteValues::isNoOverwriteValue(this.orig().(fieldId))
                || !NVTimeSheetLinesAllowedValues::isAllowedValue(this.(fieldId))))
        {

            ret = ret && checkFailed(strFmt('Date %1 : Old Value %2, New Invalid value %3 for employee %4 ', this.fieldNumToDate(fieldId), this.orig().(fieldId), this.(fieldId), this.EmpId));
        }
    }
    return ret;
}

public boolean validateAllColumnsAreFilled()
{
    int     lastDayOFMonth = dayOfMth(this.timeSheetHeader().EndDate);

    for(int day = 1; day<=lastDayOFMonth; day++)
    {
        FieldName   fieldName = "HoursDay" + int2str(day);
        int         fieldid = fieldName2Id(tableNum(NVTimeSheetLines),fieldName);

        if(this.(fieldid) == "" || this.(fieldid) == "0")
            return false;
    }
    return true;
}

public void initValue()
{
    super();

    int     lastDayOFMonth = dayOfMth(this.timeSheetHeader().EndDate);

    for(int day = 1; day<=lastDayOFMonth; day++)
    {
        FieldName   fieldName = "HoursDay" + int2str(day);
        int         fieldid = fieldName2Id(tableNum(NVTimeSheetLines),fieldName);

        this.(fieldid) = "0";
    }
}

NvTimeSheetHeader NvTimeSheetHeader()
{
    NvTimeSheetHeader   timeSheetHeader;

    select timeSheetHeader
        where timeSheetHeader.RecId == this.TimeSheetHeader;

    return timesheetHeader;
}

public TransDate fieldNumToDate(FieldId _fieldId)
{
    str fieldName = fieldId2Name(this.TableId, _fieldId);
    int day = str2int(strRem(fieldName, "HoursDay"));
    return this.TimeSheetHeader().StartDate + (day - 1);
}

private int getTotalNightHours()
{
    int totalNightHours = 0;
    NvTimeSheetHeader timeSheet = this.timeSheetHeader();
    WorkCalendarEmployment workCalendarEmployment = WorkCalendarEmployment::findByWorkerRecId(this.Worker, timeSheet.StartDate);

    if (!workCalendarEmployment.CalendarId)
        return totalNightHours;

    WorkCalendarTable workCalendarTable = WorkCalendarTable::find(workCalendarEmployment.CalendarId);

    int lastDayOfMonth  = dayOfMth(timeSheet.EndDate);
    int nightFrom       = real2int(workCalendarTable.NVNightTimeFrom);
    int nightTo         = real2int(workCalendarTable.NVNightTimeTo);

    for (int day = 1; day <= lastDayOfMonth; day++)
    {
        FieldName fieldName = strFmt("HoursDay%1", day);
        int fieldId = fieldName2Id(tableNum(NVTimeSheetLines), fieldName);

        int workedHours = this.convertStringToInt(this.(fieldId));
        if (workedHours <= 0)
            continue;

        TransDate transDate = timeSheet.StartDate + day - 1;
        WorkCalendarDate workCalendarDate;
        select firstOnly workCalendarDate
            where workCalendarDate.CalendarId       == workCalendarEmployment.CalendarId
               && workCalendarDate.TransDate        == transDate
               && workCalendarDate.WorkTimeControl  == WorkTimeControl::Open;

        if (!workCalendarDate)
            continue;

        int nightHours      = 0;
        int remainingHours  = workedHours;

        WorkCalendarDateLine workCalendarDateLine;
        while select workCalendarDateLine
            order by workCalendarDateLine.ModifiedDateTime asc
            where workCalendarDateLine.CalendarId == workCalendarDate.CalendarId
                && workCalendarDateLine.TransDate == workCalendarDate.TransDate
        {
            if (remainingHours <= 0)
                break;                

            int shiftStart = real2int(workCalendarDateLine.FromTime);
            int shiftEnd   = real2int(workCalendarDateLine.ToTime);

            int daySeconds = 24 * 60 * 60;
            if (shiftEnd <= shiftStart)
                shiftEnd += daySeconds;

            int shiftDurationHours = (shiftEnd - shiftStart) / 3600;

            int actualWorkedHours = min(remainingHours, shiftDurationHours);

            int workStart = shiftStart;
            int workEnd   = workStart + (actualWorkedHours * 3600);

            int overlapSeconds = NVTimeSheetLines::calculateNightOverlap(workStart, workEnd, nightFrom, nightTo);

            nightHours += overlapSeconds / 3600;
            remainingHours -= actualWorkedHours;
        }

        nightHours = min(nightHours, workCalendarTable.NVNightHoursCap);

        totalNightHours += nightHours;
    }

    return totalNightHours;
}

public static int calculateNightOverlap(
    int workFrom,
    int workTo,
    int nightFrom,
    int nightTo)
{
    int daySeconds = 24 * 60 * 60;

    if (workTo <= workFrom)
        workTo += daySeconds;

    if (nightTo <= nightFrom)
        nightTo += daySeconds;

    int overlap1 = max(0, min(workTo, nightTo) - max(workFrom, nightFrom));

    nightFrom -= daySeconds;
    nightTo   -= daySeconds;

    int overlap2 = max(0, min(workTo, nightTo) - max(workFrom, nightFrom));

    return overlap1 + overlap2;
}

public display int totalNightHours()
{
    return this.CalcNightHours + this.NightHours;
}

public void insert()
{
    super();

    NVHcmESSChangeLog::insertRef(this.TableId, this.RecId);
}
